('0040','constraint','ui_actions','ui_actions_route_template_check','CHECK (((route_template ~~ ''/%''::text) AND (POSITION((''?''::text) IN (route_template)) = 0) AND (POSITION((''#''::text) IN (route_template)) = 0)))|true'),
